const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Lake Sambhar geometry
  const lakeSambhar = ee.Geometry.Point([75.0, 26.9]).buffer(15000);

  // Define time periods
  const startDate2018 = '2018-01-01';
  const endDate2018 = '2018-12-31';
  const startDate2019 = '2019-01-01';
  const endDate2019 = '2019-12-31';

  // Load Sentinel-2 collections
  const s2_2018 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(lakeSambhar)
    .filterDate(startDate2018, endDate2018)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const s2_2019 = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(lakeSambhar)
    .filterDate(startDate2019, endDate2019)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  // Check if collections have data
  const count2018 = s2_2018.size().getInfo();
  const count2019 = s2_2019.size().getInfo();

  if (count2018 === 0 || count2019 === 0) {
    console.log(`2018 Images: ${count2018}, 2019 Images: ${count2019}`);
    console.log('C1');
    return;
  }

  console.log(`2018 Images: ${count2018}, 2019 Images: ${count2019}`);

  // Function to calculate water extent
  function getWaterExtent(collection, year) {
    return collection
      .map(function(img) {
        const ndwi = img.normalizedDifference(['B3', 'B8']).rename('NDWI');
        const water = ndwi.gt(0.3);
        return water;
      })
      .reduce(ee.Reducer.sum())
      .rename('water_pixels');
  }

  // Get water extent for both years
  const waterExtent2018 = getWaterExtent(s2_2018, 2018);
  const waterExtent2019 = getWaterExtent(s2_2019, 2019);

  // Calculate pixel counts
  const stats2018 = waterExtent2018.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: 20,
    maxPixels: 1e9
  }).getInfo();

  const stats2019 = waterExtent2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: lakeSambhar,
    scale: 20,
    maxPixels: 1e9
  }).getInfo();

  const pixels2018 = stats2018.water_pixels;
  const pixels2019 = stats2019.water_pixels;

  // Validate results
  if (pixels2018 === null || pixels2019 === null || pixels2018 === 0 || pixels2019 === 0) {
    console.log(`2018 Water Pixels: ${pixels2018}, 2019 Water Pixels: ${pixels2019}`);
    console.log('C2');
    return;
  }

  // Calculate extents
  const extent2018 = pixels2018 * 20 * 20 / 1e6; // Convert to km²
  const extent2019 = pixels2019 * 20 * 20 / 1e6;

  console.log(`2018 Water Extent: ${extent2018.toFixed(2)} km²`);
  console.log(`2019 Water Extent: ${extent2019.toFixed(2)} km²`);

  // Determine if water extent decreased
  if (extent2019 < extent2018) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
